--
-- TOC entry 285 (class 1255 OID 17441)
-- Name: auto_assign_grid_region_by_location(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_assign_grid_region_by_location() RETURNS void
    LANGUAGE plpgsql
    AS $$
  BEGIN
      UPDATE sites
      SET grid_region = lgm.region_code,
          grid_region_source = 'AUTO'
      FROM location_grid_mappings lgm
      WHERE (sites.grid_region IS NULL OR sites.grid_region_source != 'MANUAL')
        AND LOWER(sites.country) = LOWER(lgm.country)
        AND lgm.valid_from <= CURRENT_DATE
        AND (lgm.valid_to >= CURRENT_DATE OR lgm.valid_to IS NULL)
        AND EXISTS (
            SELECT 1
            FROM UNNEST(STRING_TO_ARRAY(REPLACE(lgm.city_pattern, ' ', ''), '|')) AS cp(city_part)
            WHERE TRIM(city_part) ILIKE '%' || COALESCE(sites.city, '') || '%'
        );
  END;
  $$;


--
-- TOC entry 286 (class 1255 OID 17439)
-- Name: auto_create_sites_from_facilities(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_create_sites_from_facilities() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
  BEGIN
      -- Only create site if this is a Facility type entity
      IF NEW.type = 'Facility' THEN
              organization_id,
              entity_id,
              name,
              country,
              city,
              lease_status,
              utility_bill_payer,
              energy_supplier_choice,
              status,
              created_at,
              updated_at
          )
          VALUES (
              NEW.organization_id,
              NEW.id,
              NEW.name,
              COALESCE(NEW.country, 'Unknown'),
              COALESCE(NEW.city, 'Unknown'),
              NEW.lease_status,
              NEW.utility_bill_payer,
              NEW.energy_supplier_choice,
              CASE WHEN NEW.status = 'EXCLUDED' THEN 'EXCLUDED' ELSE 'COMPLETE' END,
              NOW(),
              NOW()
          );
      END IF;

      RETURN NEW;
  END;
  $$;


--
-- TOC entry 295 (class 1255 OID 26269)
-- Name: auto_populate_country_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_populate_country_code() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- If country_code is not provided, try to auto-populate from country name
    IF NEW.country_code IS NULL AND NEW.country IS NOT NULL THEN
        SELECT iso_alpha3 INTO NEW.country_code
        FROM countries
        WHERE LOWER(TRIM(country_name)) = LOWER(TRIM(NEW.country));

        IF NEW.country_code IS NULL THEN
            RAISE WARNING 'Country "%" not found in countries mapping table. Please add it.', NEW.country;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


--
-- TOC entry 288 (class 1255 OID 26024)
-- Name: calculate_emission_breakdown(numeric, numeric, numeric, numeric, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_emission_breakdown(p_consumption_value numeric, p_co2_factor numeric, p_ch4_factor numeric, p_n2o_factor numeric, p_gwp_version character varying DEFAULT 'AR6'::character varying) RETURNS TABLE(co2_kg numeric, ch4_kg numeric, n2o_kg numeric, total_tco2e numeric)
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_ch4_gwp NUMERIC;
    v_n2o_gwp NUMERIC;
BEGIN
    -- GWP values based on IPCC version
    IF p_gwp_version = 'AR6' THEN
        v_ch4_gwp := 29.8;  -- IPCC AR6 100-year GWP for CH4
        v_n2o_gwp := 273;   -- IPCC AR6 100-year GWP for N2O
    ELSIF p_gwp_version = 'AR5' THEN
        v_ch4_gwp := 28;
        v_n2o_gwp := 265;
    ELSE  -- AR4 (legacy)
        v_ch4_gwp := 25;
        v_n2o_gwp := 298;
    END IF;

    RETURN QUERY
    SELECT
        p_consumption_value * COALESCE(p_co2_factor, 0) as co2_kg,
        p_consumption_value * COALESCE(p_ch4_factor, 0) as ch4_kg,
        p_consumption_value * COALESCE(p_n2o_factor, 0) as n2o_kg,
        (
            p_consumption_value * COALESCE(p_co2_factor, 0) +
            p_consumption_value * COALESCE(p_ch4_factor, 0) * v_ch4_gwp +
            p_consumption_value * COALESCE(p_n2o_factor, 0) * v_n2o_gwp
        ) / 1000 as total_tco2e;  -- Convert kg to tonnes
END;
$$;


