--

COMMENT ON FUNCTION public.calculate_emission_breakdown(p_consumption_value numeric, p_co2_factor numeric, p_ch4_factor numeric, p_n2o_factor numeric, p_gwp_version character varying) IS 'Calculates CO2, CH4, N2O in kg and total in tCO2e using specified GWP version (AR6, AR5, or AR4)';


--
-- TOC entry 296 (class 1255 OID 26277)
-- Name: calculate_emissions_before_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_emissions_before_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_ef emission_factors%ROWTYPE;
    v_breakdown RECORD;
BEGIN
    -- Only calculate if not already calculated
    -- (This allows the insert_scope1_emission() function to pre-calculate)
    IF NEW.emissions_tco2e IS NULL THEN

        -- ========================================================================
        -- STEP 1: Fetch Emission Factor
        -- ========================================================================

        IF NEW.emission_factor_id IS NULL THEN
            RAISE EXCEPTION 'emission_factor_id is required';
        END IF;

        SELECT * INTO v_ef
        FROM emission_factors
        WHERE id = NEW.emission_factor_id
          AND is_active = true;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Emission factor not found or inactive: %', NEW.emission_factor_id;
        END IF;

        -- ========================================================================
        -- STEP 2: Validate Consumption Value
        -- ========================================================================

        IF NEW.consumption_value IS NULL THEN
            RAISE EXCEPTION 'consumption_value is required';
        END IF;

        IF NEW.consumption_value <= 0 THEN
            RAISE EXCEPTION 'consumption_value must be positive, got: %', NEW.consumption_value;
        END IF;

        -- ========================================================================
        -- STEP 3: Calculate Emissions Breakdown
        -- ========================================================================

        SELECT * INTO v_breakdown
        FROM calculate_emission_breakdown(
            NEW.consumption_value,
            v_ef.co2_factor,
            v_ef.ch4_factor,
            v_ef.n2o_factor,
            COALESCE(NEW.gwp_version, v_ef.gwp_version, 'AR6')
        );

        -- ========================================================================
        -- STEP 4: Populate Calculated Fields
        -- ========================================================================

        -- Core calculations
        NEW.emissions_tco2e := v_breakdown.total_tco2e;
        NEW.co2_kg := v_breakdown.co2_kg;
        NEW.ch4_kg := v_breakdown.ch4_kg;
        NEW.n2o_kg := v_breakdown.n2o_kg;

        -- Emission factor metadata
        NEW.emission_factor_value := v_ef.factor_value;
        NEW.emission_factor_source := v_ef.source;
        NEW.gwp_version := COALESCE(NEW.gwp_version, v_ef.gwp_version, 'AR6');

        -- ========================================================================
        -- STEP 5: Auto-populate Missing Fields (if not provided)
        -- ========================================================================

        -- Fuel type and unit from emission factor
        IF NEW.fuel_type IS NULL THEN
            NEW.fuel_type := v_ef.fuel_type;
        END IF;

        IF NEW.consumption_unit IS NULL THEN
            NEW.consumption_unit := v_ef.unit;
        END IF;

        -- Data quality tier
        IF NEW.data_quality IS NULL THEN
            NEW.data_quality := COALESCE(v_ef.data_quality_tier, 'Tier 1');
        END IF;

        -- Source type default
        IF NEW.source_type IS NULL THEN
            NEW.source_type := CASE
                WHEN NEW.document_upload_id IS NOT NULL THEN 'AUTOMATED'
                ELSE 'MANUAL'
            END;
        END IF;

        -- Verification status default
        IF NEW.verification_status IS NULL THEN
            NEW.verification_status := 'pending';
        END IF;

        -- Biogenic CO2 default
        IF NEW.biogenic_co2_kg IS NULL THEN
            NEW.biogenic_co2_kg := 0;
        END IF;

    END IF;

    -- ========================================================================
    -- STEP 6: Validate Required Fields (always)
    -- ========================================================================

    IF NEW.site_id IS NULL THEN
        RAISE EXCEPTION 'site_id is required';
    END IF;

    IF NEW.year IS NULL THEN
        RAISE EXCEPTION 'year is required';
    END IF;

    IF NEW.month IS NOT NULL AND (NEW.month < 1 OR NEW.month > 12) THEN
        RAISE EXCEPTION 'month must be between 1 and 12, got: %', NEW.month;
    END IF;

    RETURN NEW;
END;
$$;


