--
-- TOC entry 284 (class 1255 OID 17385)
-- Name: calculate_scope_eligibility(character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_scope_eligibility(p_lease_status character varying, p_utility_bill_payer character varying, p_energy_supplier_choice character varying, p_boundary_method character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
  BEGIN
      IF p_boundary_method = 'Operational Control' THEN
          IF p_lease_status = 'Leased – Full Control' AND
             p_utility_bill_payer = 'Company' AND
             p_energy_supplier_choice = 'Company' THEN
              RETURN 'Scope 2 Eligible';
          ELSIF p_lease_status = 'Leased – No Control' THEN
              RETURN 'Not in Scope 2 → Scope 3';
          ELSIF p_lease_status IN ('Leased – Partial Control', 'Owned') THEN
              IF p_lease_status = 'Owned' THEN
                  RETURN 'Scope 2 Eligible';
              ELSE
                  RETURN 'Partial Control - Review';
              END IF;
          ELSE
              RETURN 'Scope 2 Eligible';
          END IF;
      ELSIF p_boundary_method = 'Financial Control' THEN
          RETURN 'Scope 2 Eligible';
      ELSIF p_boundary_method = 'Equity Share' THEN
          RETURN 'Scope 2 Eligible';
      ELSE
          RETURN 'Unknown Boundary Method';
      END IF;
  END;
  $$;


--
-- TOC entry 292 (class 1255 OID 26319)
-- Name: get_active_electricity_contract(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_electricity_contract(p_site_id uuid, p_year integer, p_month integer) RETURNS TABLE(contract_id uuid, contract_name character varying, provider_name character varying, contract_type character varying, renewable_percentage numeric, emission_factor_gco2_kwh numeric, emission_factor_source character varying)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_reporting_date DATE;
BEGIN
    -- Construct reporting date (middle of month)
    v_reporting_date := make_date(p_year, p_month, 15);

    RETURN QUERY
    SELECT
        ec.id,
        ec.contract_name,
        ec.provider_name,
        ec.contract_type,
        ec.renewable_percentage,
        ec.emission_factor_gco2_kwh,
        ec.emission_factor_source
    FROM electricity_contracts ec
    WHERE ec.site_id = p_site_id
      AND ec.is_active = true
      AND ec.start_date <= v_reporting_date
      AND ec.end_date >= v_reporting_date
    ORDER BY ec.created_at DESC  -- Most recent contract if overlapping
    LIMIT 1;
END;
$$;


