--
-- TOC entry 294 (class 1255 OID 26275)
-- Name: get_emission_factors_for_selection(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_emission_factors_for_selection(p_fuel_group_id uuid, p_site_id uuid) RETURNS TABLE(id uuid, display_name text, factor_value numeric, unit character varying, source character varying, source_year integer, location_priority integer, co2_factor numeric, ch4_factor numeric, n2o_factor numeric, description text)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    WITH site_location AS (
        SELECT
            s.country_code,      -- ✅ NOW USING country_code instead of country
            s.grid_region
        FROM sites s
        WHERE s.id = p_site_id
    ),
    available_factors AS (
        SELECT DISTINCT
            ef.id,
            ef.fuel_type,
            ef.unit,
            ef.factor_value,
            ef.source,
            ef.source_year,
            ef.country_code,
            ef.region,
            ef.geographic_scope,
            ef.co2_factor,
            ef.ch4_factor,
            ef.n2o_factor,
            ef.description,
            sl.country_code as site_country_code,
            sl.grid_region as site_region,
            CASE
                WHEN ef.country_code = sl.country_code THEN 1    -- ✅ NOW COMPARING CODES
                WHEN ef.region = sl.grid_region THEN 2           -- Regional match
                WHEN ef.geographic_scope = 'Global' THEN 3       -- Global fallback
                ELSE 4                                            -- No match
            END as location_priority,
            CONCAT(
                ef.fuel_type, ' - ', ef.unit,
                ' (', ef.source, ' ', ef.source_year::TEXT,
                CASE
                    WHEN ef.country_code = sl.country_code THEN ' - ' || ef.country_code || ' ✓'
                    WHEN ef.region = sl.grid_region THEN ' - ' || ef.region
                    WHEN ef.geographic_scope = 'Global' THEN ' - Global'
                    ELSE ''
                END, ')'
            ) as display_name
        FROM emission_factors ef
        CROSS JOIN site_location sl
        JOIN emission_factor_classifications efc ON ef.id = efc.emission_factor_id
        WHERE efc.fuel_group_id = p_fuel_group_id
          AND ef.is_active = true
          AND (
              ef.country_code = sl.country_code
              OR ef.region = sl.grid_region
              OR ef.geographic_scope = 'Global'
              OR ef.country_code IS NULL
          )
    )
    SELECT
        af.id,
        af.display_name,
        af.factor_value,
        af.unit,
        af.source,
        af.source_year,
        af.location_priority,
        af.co2_factor,
        af.ch4_factor,
        af.n2o_factor,
        af.description
    FROM available_factors af
    ORDER BY af.location_priority ASC, af.source_year DESC, af.source;
END;
$$;


