--
-- TOC entry 272 (class 1255 OID 26279)
-- Name: insert_scope1_emission(uuid, integer, integer, uuid, numeric, uuid, character varying, character varying, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insert_scope1_emission(p_site_id uuid, p_year integer, p_month integer, p_emission_factor_id uuid, p_consumption_value numeric, p_uploaded_by uuid, p_combustion_type character varying DEFAULT NULL::character varying, p_equipment_type character varying DEFAULT NULL::character varying, p_notes text DEFAULT NULL::text, p_document_upload_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_emission_id UUID;
    v_ef emission_factors%ROWTYPE;
    v_breakdown RECORD;
    v_site_exists BOOLEAN;
BEGIN
    -- ========================================================================
    -- STEP 1: Validate Inputs
    -- ========================================================================

    -- Validate site exists
    SELECT EXISTS(SELECT 1 FROM sites WHERE id = p_site_id) INTO v_site_exists;
    IF NOT v_site_exists THEN
        RAISE EXCEPTION 'Site not found: %', p_site_id;
    END IF;

    -- Validate year
    IF p_year IS NULL THEN
        RAISE EXCEPTION 'Year is required';
    END IF;

    IF p_year < 2000 OR p_year > 2100 THEN
        RAISE EXCEPTION 'Year must be between 2000 and 2100, got: %', p_year;
    END IF;

    -- Validate month
    IF p_month IS NOT NULL AND (p_month < 1 OR p_month > 12) THEN
        RAISE EXCEPTION 'Month must be between 1 and 12, got: %', p_month;
    END IF;

    -- Validate emission factor
    IF p_emission_factor_id IS NULL THEN
        RAISE EXCEPTION 'Emission factor ID is required';
    END IF;

    -- Validate consumption value
    IF p_consumption_value IS NULL THEN
        RAISE EXCEPTION 'Consumption value is required';
    END IF;

    IF p_consumption_value <= 0 THEN
        RAISE EXCEPTION 'Consumption value must be positive, got: %', p_consumption_value;
    END IF;

    -- Validate user
    IF p_uploaded_by IS NULL THEN
        RAISE EXCEPTION 'User ID (uploaded_by) is required';
    END IF;

    -- ========================================================================
    -- STEP 2: Fetch Emission Factor
    -- ========================================================================

    SELECT * INTO v_ef
    FROM emission_factors
    WHERE id = p_emission_factor_id
      AND is_active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Emission factor not found or inactive: %', p_emission_factor_id;
    END IF;

    -- Additional validation: Must be Scope 1
    IF v_ef.scope != 1 THEN
        RAISE EXCEPTION 'Invalid emission factor: Must be Scope 1, got Scope %', v_ef.scope;
    END IF;

    -- ========================================================================
    -- STEP 3: Calculate Emissions Breakdown
    -- ========================================================================

    SELECT * INTO v_breakdown
    FROM calculate_emission_breakdown(
        p_consumption_value,
        v_ef.co2_factor,
        v_ef.ch4_factor,
        v_ef.n2o_factor,
        v_ef.gwp_version
    );

    -- Validate calculation succeeded
    IF v_breakdown.total_tco2e IS NULL THEN
        RAISE EXCEPTION 'Emission calculation failed for factor: %', p_emission_factor_id;
    END IF;

    -- ========================================================================
    -- STEP 4: Insert Record with All Fields Populated
    -- ========================================================================

        site_id,
        year,
        month,
        fuel_type,
        consumption_unit,
        consumption_value,
        emission_factor_id,
        emission_factor_source,
        emission_factor_value,
        emissions_tco2e,
        co2_kg,
        ch4_kg,
        n2o_kg,
        biogenic_co2_kg,
        gwp_version,
        uncertainty_pct,
        combustion_type,
        equipment_type,
        data_quality,
        source_type,
        uploaded_by,
        notes,
        document_upload_id,
        is_manual_entry,
        verification_status,
        calculation_method
    ) VALUES (
        p_site_id,
        p_year,
        p_month,
        v_ef.fuel_type,
        v_ef.unit,
        p_consumption_value,
        p_emission_factor_id,
        v_ef.source,
        v_ef.factor_value,
        v_breakdown.total_tco2e,      -- Pre-calculated ✅
        v_breakdown.co2_kg,            -- Pre-calculated ✅
        v_breakdown.ch4_kg,            -- Pre-calculated ✅
        v_breakdown.n2o_kg,            -- Pre-calculated ✅
        0,                             -- biogenic_co2_kg (default)
        v_ef.gwp_version,
        v_ef.uncertainty_pct,
        p_combustion_type,
        p_equipment_type,
        COALESCE(v_ef.data_quality_tier, 'Tier 1'),
        'MANUAL',
        p_uploaded_by,
        p_notes,
        p_document_upload_id,
        true,                          -- is_manual_entry
        'pending',                     -- verification_status
        'ACTIVITY_BASED'               -- calculation_method
    ) RETURNING id INTO v_emission_id;

    -- ========================================================================
    -- STEP 5: Trigger Fires (but does nothing since fields populated)
    -- ========================================================================

    -- Note: trg_calculate_emissions sees emissions_tco2e NOT NULL
    --       and skips calculation (no conflict!)

    -- Note: trg_log_factor_usage and trg_audit_emission_changes
    --       still fire and log to respective tables ✅

    -- ========================================================================
    -- STEP 6: Return New Emission Entry ID
    -- ========================================================================

    RETURN v_emission_id;

EXCEPTION
    WHEN OTHERS THEN
        -- Re-raise with context
        RAISE EXCEPTION 'Failed to insert Scope 1 emission: %', SQLERRM;
END;
$$;


--
-- TOC entry 5507 (class 0 OID 0)
-- Dependencies: 272
-- Name: FUNCTION insert_scope1_emission(p_site_id uuid, p_year integer, p_month integer, p_emission_factor_id uuid, p_consumption_value numeric, p_uploaded_by uuid, p_combustion_type character varying, p_equipment_type character varying, p_notes text, p_document_upload_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.insert_scope1_emission(p_site_id uuid, p_year integer, p_month integer, p_emission_factor_id uuid, p_consumption_value numeric, p_uploaded_by uuid, p_combustion_type character varying, p_equipment_type character varying, p_notes text, p_document_upload_id uuid) IS 'Inserts a Scope 1 emission entry with automatic calculations.
Designed for manual UI entry workflow with pre-validation and better error messages.
Pre-calculates emissions breakdown before INSERT, making it compatible with the
trg_calculate_emissions trigger (which skips calculation if already done).

Parameters:
- p_site_id: Site/facility UUID (required)
- p_year: Reporting year (required, 2000-2100)
- p_month: Reporting month (optional, 1-12)
- p_emission_factor_id: Selected emission factor UUID (required, must be Scope 1)
- p_consumption_value: Amount consumed (required, positive number)
- p_uploaded_by: User UUID (required)
- p_combustion_type: Type of combustion (optional, e.g., "Stationary", "Mobile")
- p_equipment_type: Equipment used (optional, e.g., "Boiler", "Company Car")
- p_notes: Additional notes (optional)
- p_document_upload_id: Reference to uploaded document (optional)

Returns: UUID of newly created emission entry

Automatic Actions:
- Fetches emission factor details
- Calculates CO2, CH4, N2O breakdown using calculate_emission_breakdown()
- Applies GWP based on factor version (AR6/AR5/AR4)
- Logs factor usage via trg_log_factor_usage trigger
- Creates audit trail via trg_audit_emission_changes trigger

Example:
  SELECT insert_scope1_emission(
      p_site_id := ''site-uuid'',
      p_year := 2025,
      p_month := 10,
      p_emission_factor_id := ''factor-uuid'',
      p_consumption_value := 1000,
      p_uploaded_by := ''user-uuid'',
      p_combustion_type := ''Stationary'',
      p_equipment_type := ''Natural Gas Boiler'',
      p_notes := ''October heating fuel''
  );
';


--
-- TOC entry 291 (class 1255 OID 26324)
-- Name: insert_scope2_emission(uuid, integer, integer, character varying, numeric, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insert_scope2_emission(p_site_id uuid, p_year integer, p_month integer, p_energy_type character varying, p_consumption_value numeric, p_uploaded_by uuid, p_emission_factor_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_document_upload_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_emission_id UUID;
    v_site sites%ROWTYPE;
    v_contract electricity_contracts%ROWTYPE;
    v_grid_region grid_regions%ROWTYPE;
    v_ef emission_factors%ROWTYPE;
    v_breakdown RECORD;
    v_methodology VARCHAR(20);
    v_factor_source VARCHAR(200);
    v_supplier_name VARCHAR(200);
    v_co2_factor NUMERIC;
    v_ch4_factor NUMERIC;
    v_n2o_factor NUMERIC;
    v_factor_value NUMERIC;
    v_gwp_version VARCHAR(10);
BEGIN
    -- ========================================================================
    -- STEP 1: Validate Inputs
    -- ========================================================================

    -- Validate site exists
    SELECT * INTO v_site FROM sites WHERE id = p_site_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Site not found: %', p_site_id;
    END IF;

    -- Validate year
    IF p_year IS NULL THEN
        RAISE EXCEPTION 'Year is required';
    END IF;

    IF p_year < 2000 OR p_year > 2100 THEN
        RAISE EXCEPTION 'Year must be between 2000 and 2100, got: %', p_year;
    END IF;

    -- Validate month
    IF p_month IS NOT NULL AND (p_month < 1 OR p_month > 12) THEN
        RAISE EXCEPTION 'Month must be between 1 and 12, got: %', p_month;
    END IF;

    -- Validate energy type
    IF p_energy_type NOT IN ('Electricity', 'Heat', 'Steam', 'Cooling') THEN
        RAISE EXCEPTION 'Invalid energy type: %. Must be Electricity, Heat, Steam, or Cooling', p_energy_type;
    END IF;

    -- Validate consumption value
    IF p_consumption_value IS NULL THEN
        RAISE EXCEPTION 'Consumption value is required';
    END IF;

    IF p_consumption_value <= 0 THEN
        RAISE EXCEPTION 'Consumption value must be positive, got: %', p_consumption_value;
    END IF;

    -- Validate user
    IF p_uploaded_by IS NULL THEN
        RAISE EXCEPTION 'User ID (uploaded_by) is required';
    END IF;

    -- ========================================================================
    -- STEP 2: ELECTRICITY PATH - Use grid_regions Table
    -- ========================================================================

    IF p_energy_type = 'Electricity' THEN

        -- Check if site has active renewable contract for this period (market-based)
        SELECT * INTO v_contract
        FROM get_active_electricity_contract(p_site_id, p_year, p_month);

        IF FOUND THEN
            -- ===============================================================
            -- MARKET-BASED METHOD (Contract exists)
            -- ===============================================================

            v_methodology := 'MARKET_BASED';
            v_factor_source := v_contract.contract_name || ' (' || v_contract.provider_name || ')';
            v_supplier_name := v_contract.provider_name;

            -- Use contract emission factor (usually 0 for 100% renewable)
            v_factor_value := v_contract.emission_factor_gco2_kwh;
            v_co2_factor := v_contract.emission_factor_gco2_kwh / 1000;  -- Convert gCO2e to kgCO2e
            v_ch4_factor := 0;  -- Renewable contracts typically zero CH4
            v_n2o_factor := 0;  -- Renewable contracts typically zero N2O
            v_gwp_version := 'AR6';

            RAISE NOTICE 'Market-based contract found: % with factor % gCO2e/kWh',
                v_contract.contract_name, v_contract.emission_factor_gco2_kwh;

        ELSE
            -- ===============================================================
            -- LOCATION-BASED METHOD (No contract - use grid)
            -- ===============================================================

            v_methodology := 'LOCATION_BASED';
            v_factor_source := 'Grid Average';
            v_supplier_name := 'Grid Supply';

            -- Try to get grid factor by grid_region code first
            IF v_site.grid_region IS NOT NULL THEN
                SELECT * INTO v_grid_region
                FROM grid_regions
                WHERE code = v_site.grid_region
                  AND CURRENT_DATE BETWEEN validity_start_date AND COALESCE(validity_end_date, '9999-12-31'::DATE)
                LIMIT 1;

                IF FOUND THEN
                    RAISE NOTICE 'Found grid factor for grid_region: %', v_site.grid_region;
                END IF;
            END IF;

            -- Fallback to country-level grid if grid_region not found
            IF NOT FOUND AND v_site.country_code IS NOT NULL THEN
                SELECT * INTO v_grid_region
                FROM grid_regions
                WHERE country_code = v_site.country_code
                  AND CURRENT_DATE BETWEEN validity_start_date AND COALESCE(validity_end_date, '9999-12-31'::DATE)
                ORDER BY code
                LIMIT 1;

                IF FOUND THEN
                    RAISE NOTICE 'Using country-level grid factor for: %', v_site.country_code;
                END IF;
            END IF;

            -- If still not found, error
            IF NOT FOUND THEN
                RAISE EXCEPTION 'No electricity grid factor found for site. Grid region: %, Country: %',
                    v_site.grid_region, v_site.country_code;
            END IF;

            -- Extract factors from grid_regions table
            v_factor_value := v_grid_region.default_ef_value * 1000;  -- Convert kgCO2e to gCO2e for consistency
            v_factor_source := v_grid_region.name || ' (' || v_grid_region.source || ')';

            -- Parse JSONB description for CO2, CH4, N2O breakdown
            -- Format: {"ch4": 0.003, "co2": 0.228, "n2o": 0.002}
            IF v_grid_region.description IS NOT NULL THEN
                v_co2_factor := COALESCE((v_grid_region.description->>'co2')::NUMERIC, v_grid_region.default_ef_value);
                v_ch4_factor := COALESCE((v_grid_region.description->>'ch4')::NUMERIC, 0);
                v_n2o_factor := COALESCE((v_grid_region.description->>'n2o')::NUMERIC, 0);
            ELSE
                -- If no breakdown, use total as CO2
                v_co2_factor := v_grid_region.default_ef_value;
                v_ch4_factor := 0;
                v_n2o_factor := 0;
            END IF;

            v_gwp_version := 'AR6';
        END IF;

        -- Calculate emissions breakdown for electricity
        SELECT * INTO v_breakdown
        FROM calculate_emission_breakdown(
            p_consumption_value,
            v_co2_factor,
            v_ch4_factor,
            v_n2o_factor,
            v_gwp_version
        );

    ELSE
        -- ========================================================================
        -- STEP 3: HEAT/STEAM/COOLING PATH - Use emission_factors Table
        -- ========================================================================

        v_methodology := 'LOCATION_BASED';  -- Heat/Steam/Cooling always location-based
        v_supplier_name := 'District/Network Provider';

        IF p_emission_factor_id IS NOT NULL THEN
            -- Manual factor selection by user
            SELECT * INTO v_ef
            FROM emission_factors
            WHERE id = p_emission_factor_id
              AND is_active = true;

            IF NOT FOUND THEN
                RAISE EXCEPTION 'Emission factor not found or inactive: %', p_emission_factor_id;
            END IF;

            -- Validate it's Scope 2
            IF v_ef.scope != 2 THEN
                RAISE EXCEPTION 'Invalid emission factor: Must be Scope 2, got Scope %', v_ef.scope;
            END IF;

        ELSE
            -- Auto-select emission factor based on energy type and site location
            SELECT * INTO v_ef
            FROM emission_factors
            WHERE scope = 2
              AND (
                  (p_energy_type = 'Heat' AND category LIKE '%Heat%') OR
                  (p_energy_type = 'Steam' AND category LIKE '%Steam%') OR
                  (p_energy_type = 'Cooling' AND category LIKE '%Cooling%')
              )
              AND is_active = true
              AND (
                  country_code = v_site.country_code OR
                  geographic_scope = 'Global'
              )
            ORDER BY
                CASE
                    WHEN country_code = v_site.country_code THEN 1
                    WHEN geographic_scope = 'Global' THEN 2
                    ELSE 3
                END,
                validity_start_date DESC
            LIMIT 1;

            IF NOT FOUND THEN
                RAISE EXCEPTION 'No % emission factor found for country: %',
                    p_energy_type, v_site.country_code;
            END IF;
        END IF;

        v_factor_value := v_ef.factor_value;
        v_factor_source := v_ef.display_name;

        -- Calculate emissions breakdown for heat/steam/cooling
        SELECT * INTO v_breakdown
        FROM calculate_emission_breakdown(
            p_consumption_value,
            v_ef.co2_factor,
            COALESCE(v_ef.ch4_factor, 0),
            COALESCE(v_ef.n2o_factor, 0),
            COALESCE(v_ef.gwp_version, 'AR6')
        );

        v_gwp_version := COALESCE(v_ef.gwp_version, 'AR6');
    END IF;

    -- ========================================================================
    -- STEP 4: Validate Calculation Succeeded
    -- ========================================================================

    IF v_breakdown.total_tco2e IS NULL THEN
        RAISE EXCEPTION 'Emission calculation failed';
    END IF;

    -- ========================================================================
    -- STEP 5: Insert Record into emissions_scope_2 Table
    -- ========================================================================

        site_id,
        year,
        month,
        energy_type,
        consumption_unit,
        consumption_value,
        emission_factor_id,
        emission_factor_source,
        emission_factor_value,
        emissions_tco2e,
        co2_kg,
        ch4_kg,
        n2o_kg,
        gwp_version,
        methodology,
        electricity_contract_id,
        supplier_name,
        data_quality,
        source_type,
        uploaded_by,
        notes,
        document_upload_id,
        is_manual_entry,
        verification_status,
        calculation_method
    ) VALUES (
        p_site_id,
        p_year,
        p_month,
        p_energy_type,
        'kWh',
        p_consumption_value,
        CASE WHEN p_energy_type = 'Electricity' THEN NULL ELSE v_ef.id END,  -- NULL for electricity (uses grid_regions)
        v_factor_source,
        v_factor_value,
        v_breakdown.total_tco2e,
        v_breakdown.co2_kg,
        v_breakdown.ch4_kg,
        v_breakdown.n2o_kg,
        v_gwp_version,
        v_methodology,  -- 'MARKET_BASED' or 'LOCATION_BASED'
        CASE WHEN v_methodology = 'MARKET_BASED' THEN v_contract.contract_id ELSE NULL END,
        v_supplier_name,
        'Tier 2',  -- Default data quality
        'MANUAL',
        p_uploaded_by,
        p_notes,
        p_document_upload_id,
        true,
        'pending',
        'ACTIVITY_BASED'
    ) RETURNING id INTO v_emission_id;

    -- ========================================================================
    -- STEP 6: Return New Emission Entry ID
    -- ========================================================================

    RETURN v_emission_id;

EXCEPTION
    WHEN OTHERS THEN
        -- Re-raise with context
        RAISE EXCEPTION 'Failed to insert Scope 2 emission: %', SQLERRM;
END;
$$;


--
-- TOC entry 5508 (class 0 OID 0)
-- Dependencies: 291
-- Name: FUNCTION insert_scope2_emission(p_site_id uuid, p_year integer, p_month integer, p_energy_type character varying, p_consumption_value numeric, p_uploaded_by uuid, p_emission_factor_id uuid, p_notes text, p_document_upload_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.insert_scope2_emission(p_site_id uuid, p_year integer, p_month integer, p_energy_type character varying, p_consumption_value numeric, p_uploaded_by uuid, p_emission_factor_id uuid, p_notes text, p_document_upload_id uuid) IS 'Inserts a Scope 2 emission entry with automatic methodology detection and calculations.
REVISED VERSION - Uses hybrid approach: grid_regions for electricity, emission_factors for heat/steam/cooling.

METHODOLOGY:
- Electricity with active contract → Market-Based (uses contract factor, often 0)
- Electricity without contract → Location-Based (uses grid_regions table)
- Heat/Steam/Cooling → Location-Based (uses emission_factors table)

FACTOR SELECTION:
- Electricity: Queries grid_regions by site.grid_region code, fallback to country_code
- Heat/Steam/Cooling: Queries emission_factors by energy_type + country_code
- Parses JSONB description for CH4/N2O breakdown from grid_regions
- Converts kgCO2e/kWh → tCO2e

Parameters:
- p_site_id: Site/facility UUID (required)
- p_year: Reporting year (required, 2000-2100)
- p_month: Reporting month (optional, 1-12)
- p_energy_type: Type of energy (required: Electricity, Heat, Steam, Cooling)
- p_consumption_value: Amount consumed in kWh (required, positive number)
- p_uploaded_by: User UUID (required)
- p_emission_factor_id: Manual factor selection (optional, for Heat/Steam/Cooling only)
- p_notes: Additional notes (optional)
- p_document_upload_id: Reference to uploaded document (optional)

Returns: UUID of newly created emission entry

Automatic Actions:
- Checks for active electricity contracts (market-based method)
- Fetches grid factor from grid_regions table (for electricity)
- Fetches emission factor from emission_factors table (for heat/steam/cooling)
- Calculates CO2, CH4, N2O breakdown
- Logs methodology used (market-based vs location-based)
- Creates audit trail

Example:
  SELECT insert_scope2_emission(
      p_site_id := ''site-uuid'',
      p_year := 2025,
      p_month := 10,
      p_energy_type := ''Electricity'',
      p_consumption_value := 5000,
      p_uploaded_by := ''user-uuid'',
      p_notes := ''October electricity consumption''
  );
';


--
-- TOC entry 289 (class 1255 OID 26091)
-- Name: log_emission_calculation_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_emission_calculation_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
            emission_entry_id,
            action,
            new_value,
            changed_fields,
            calculation_details,
            changed_by,
            ip_address
        ) VALUES (
            NEW.id,
            'created',
            to_jsonb(NEW),
            ARRAY['*'],  -- All fields
            jsonb_build_object(
                'formula', CONCAT(
                    NEW.consumption_value::TEXT, ' ', NEW.consumption_unit,
                    ' × ', NEW.emission_factor_value::TEXT,
                    ' = ', NEW.emissions_tco2e::TEXT, ' tCO₂e'
                ),
                'source', NEW.emission_factor_source,
                'method', NEW.calculation_method,
                'gwp_version', NEW.gwp_version
            ),
            NEW.uploaded_by,
            inet_client_addr()  -- Capture IP if available
        );
        RETURN NEW;

    ELSIF TG_OP = 'UPDATE' THEN
            emission_entry_id,
            action,
            old_value,
            new_value,
            changed_fields,
            calculation_details,
            changed_by,
            ip_address
        ) VALUES (
            NEW.id,
            CASE
                WHEN OLD.verification_status != NEW.verification_status AND NEW.verification_status = 'verified' THEN 'verified'
                WHEN OLD.verification_status != NEW.verification_status AND NEW.verification_status = 'rejected' THEN 'rejected'
                ELSE 'updated'
            END,
            to_jsonb(OLD),
            to_jsonb(NEW),
            ARRAY(
                SELECT DISTINCT unnest(ARRAY[
                    CASE WHEN OLD.consumption_value != NEW.consumption_value THEN 'consumption_value' END,
                    CASE WHEN OLD.emission_factor_value != NEW.emission_factor_value THEN 'emission_factor_value' END,
                    CASE WHEN OLD.emissions_tco2e != NEW.emissions_tco2e THEN 'emissions_tco2e' END,
                    CASE WHEN OLD.verification_status != NEW.verification_status THEN 'verification_status' END,
                    CASE WHEN OLD.data_quality != NEW.data_quality THEN 'data_quality' END
                ])
                WHERE unnest IS NOT NULL
            ),
            jsonb_build_object(
                'old_formula', CONCAT(OLD.consumption_value::TEXT, ' × ', OLD.emission_factor_value::TEXT, ' = ', OLD.emissions_tco2e::TEXT),
                'new_formula', CONCAT(NEW.consumption_value::TEXT, ' × ', NEW.emission_factor_value::TEXT, ' = ', NEW.emissions_tco2e::TEXT),
                'reason', NEW.notes
            ),
            NEW.uploaded_by,
            inet_client_addr()
        );
        RETURN NEW;

    ELSIF TG_OP = 'DELETE' THEN
            emission_entry_id,
            action,
            old_value,
            changed_by
        ) VALUES (
            OLD.id,
            'deleted',
            to_jsonb(OLD),
            OLD.uploaded_by
        );
        RETURN OLD;
    END IF;
END;
$$;


--
-- TOC entry 290 (class 1255 OID 26093)
-- Name: log_emission_factor_usage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_emission_factor_usage() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_ef emission_factors%ROWTYPE;
BEGIN
    IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND (OLD.emission_factor_id IS DISTINCT FROM NEW.emission_factor_id)) THEN
        -- Get emission factor details
        SELECT * INTO v_ef FROM emission_factors WHERE id = NEW.emission_factor_id;

        IF FOUND THEN
                emission_factor_id,
                emission_entry_id,
                factor_value_used,
                factor_source,
                factor_region,
                factor_year,
                applied_by,
                is_override,
                override_reason
            ) VALUES (
                NEW.emission_factor_id,
                NEW.id,
                NEW.emission_factor_value,
                NEW.emission_factor_source,
                v_ef.region,
                v_ef.source_year,
                NEW.uploaded_by,
                (NEW.emission_factor_value != v_ef.factor_value),  -- True if user overrode factor
                CASE
                    WHEN NEW.emission_factor_value != v_ef.factor_value THEN
                        CONCAT('User override: ', NEW.emission_factor_value::TEXT, ' (original: ', v_ef.factor_value::TEXT, ')')
                    ELSE NULL
                END
            );
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


