--
-- TOC entry 293 (class 1255 OID 26320)
-- Name: validate_contract_no_overlap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_contract_no_overlap() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_overlap_count INTEGER;
BEGIN
    -- Check for overlapping contracts for the same site
    SELECT COUNT(*) INTO v_overlap_count
    FROM electricity_contracts
    WHERE site_id = NEW.site_id
      AND id != COALESCE(NEW.id, gen_random_uuid())  -- Exclude self on UPDATE
      AND is_active = true
      AND (
          (NEW.start_date BETWEEN start_date AND end_date) OR
          (NEW.end_date BETWEEN start_date AND end_date) OR
          (start_date BETWEEN NEW.start_date AND NEW.end_date)
      );

    IF v_overlap_count > 0 THEN
        RAISE WARNING 'Contract period overlaps with existing contract for site. Multiple contracts may cause ambiguity.';
    END IF;

    RETURN NEW;
END;
$$;


