CREATE MATERIALIZED VIEW public.v_activity_types_by_category AS
 SELECT emission_category_id,
    json_agg(json_build_object('id', id, 'name', activity_name, 'code', activity_code, 'description', description, 'icon', icon, 'sortOrder', sort_order) ORDER BY sort_order) AS activity_types
   FROM public.activity_types
  WHERE (is_active = true)
  GROUP BY emission_category_id
  WITH NO DATA;


