--
-- TOC entry 259 (class 1259 OID 26076)
-- Name: v_scope1_audit_trail; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.v_scope1_audit_trail AS
 SELECT cal.id,
    cal.emission_entry_id,
    es1.fuel_type,
    es1.consumption_value,
    es1.consumption_unit,
    s.name AS site_name,
    cal.action,
    cal.changed_by,
    u.name AS changed_by_name,
    u.email AS changed_by_email,
    cal.changed_at,
    cal.change_reason,
    (cal.old_value)::text AS old_value_json,
    (cal.new_value)::text AS new_value_json,
    (cal.calculation_details)::text AS calculation_details_json
   FROM (((public.calculation_audit_log cal
     LEFT JOIN public.emissions_scope_1 es1 ON ((cal.emission_entry_id = es1.id)))
     LEFT JOIN public.sites s ON ((es1.site_id = s.id)))
     LEFT JOIN public.users u ON ((cal.changed_by = u.id)))
  ORDER BY cal.changed_at DESC
  WITH NO DATA;


--
-- TOC entry 5541 (class 0 OID 0)
-- Dependencies: 259
-- Name: MATERIALIZED VIEW v_scope1_audit_trail; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON MATERIALIZED VIEW public.v_scope1_audit_trail IS 'Human-readable audit trail with user names and site names. Refresh hourly for compliance reporting.';


--
-- TOC entry 258 (class 1259 OID 26062)
-- Name: v_scope1_monthly_summary; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.v_scope1_monthly_summary AS
 SELECT es.site_id,
    s.name AS site_name,
    es.year,
    es.month,
    es.fuel_type,
    count(*) AS entry_count,
    sum(es.consumption_value) AS total_consumption,
    es.consumption_unit,
    sum(es.emissions_tco2e) AS total_tco2e,
    sum(es.co2_kg) AS total_co2_kg,
    sum(es.ch4_kg) AS total_ch4_kg,
    sum(es.n2o_kg) AS total_n2o_kg,
    avg(
        CASE
            WHEN ((es.data_quality)::text = 'A'::text) THEN 4
            WHEN ((es.data_quality)::text = 'B'::text) THEN 3
            WHEN ((es.data_quality)::text = 'C'::text) THEN 2
            WHEN ((es.data_quality)::text = 'D'::text) THEN 1
            ELSE 0
        END) AS avg_quality_score,
    max(es.updated_at) AS last_updated
   FROM (public.emissions_scope_1 es
     JOIN public.sites s ON ((es.site_id = s.id)))
  GROUP BY es.site_id, s.name, es.year, es.month, es.fuel_type, es.consumption_unit
  WITH NO DATA;


--
-- TOC entry 5542 (class 0 OID 0)
-- Dependencies: 258
-- Name: MATERIALIZED VIEW v_scope1_monthly_summary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON MATERIALIZED VIEW public.v_scope1_monthly_summary IS 'Monthly aggregation of Scope 1 emissions by site and fuel type. Refresh daily or after bulk imports.';


